  #localizedDescription(rawDescription) {
    try {
      const details = JSON.parse(rawDescription)

      if (details.added_at && details.updated_at) {
        const assignees = details.assignees.length ? `assigned to ${this.#toSentence(details.assignees)}` : "not assigned"
        return `Added ${formatTimestamp(new Date(details.added_at), "date")} by ${details.author} and ${assignees}. Updated ${formatTimestamp(new Date(details.updated_at), "date")}`
      }
    } catch {
      // Board share descriptions are plain text, not structured timestamp data.
    }

    return rawDescription
  }

  #toSentence(items) {
    if (items.length < 2) return items[0]
    if (items.length === 2) return items.join(" and ")
    return `${items.slice(0, -1).join(", ")}, and ${items.at(-1)}`
  }
